CREATE OR REPLACE FUNCTION generate_performance_alert()
RETURNS TRIGGER AS $$
DECLARE
    v_panel_powratew numeric;
    v_plant_initdate date;
    v_years_since_install numeric;
    v_expected_ppr numeric;
    v_current_ppr numeric;
    v_critical_threshold numeric;
    v_replace_prior character varying;
    v_existing_alert_id character varying;
    v_random_hash character varying;
BEGIN
    -- Get panel rated power
    SELECT p.powratew INTO v_panel_powratew
    FROM panel p
    WHERE p.panemark = NEW.deviceref;

    -- Get plant installation date via panel's hubregistry -> plant.growregistry
    SELECT pl.initdate INTO v_plant_initdate
    FROM panel p
    JOIN plant pl ON p.hubregistry = pl.growregistry
    WHERE p.panemark = NEW.deviceref;

    -- Calculate years since installation
    v_years_since_install := EXTRACT(YEAR FROM AGE(NEW.perfmoment, v_plant_initdate));

    -- Expected PPR accounts for normal degradation (~0.7% per year)
    -- Expected = 100 * (1 - 0.007 * years_since_install)
    v_expected_ppr := 100.0 * (1.0 - 0.007 * v_years_since_install);

    -- Current PPR = measured power / rated power * 100
    v_current_ppr := (NEW.measpoww / v_panel_powratew) * 100.0;

    -- Critical threshold: PPR falls below 80% of expected value
    v_critical_threshold := v_expected_ppr * 0.80;

    -- Determine replacement priority based on performance level
    IF v_current_ppr < (v_expected_ppr * 0.60) THEN
        v_replace_prior := 'High';
    ELSE
        v_replace_prior := 'Medium';
    END IF;

    -- Check if a similar alert exists within the last 30 days
    SELECT a.alertreg INTO v_existing_alert_id
    FROM alerts a
    WHERE a.deviceref = NEW.deviceref
      AND a.incidentref = NEW.perfregistry
      AND a.alertmoment >= (NEW.perfmoment - INTERVAL '30 days')
    LIMIT 1;

    IF v_existing_alert_id IS NOT NULL THEN
        -- Update existing alert instead of creating duplicate
        UPDATE alerts
        SET alertstat = 'Critical',
            maintprior = 'High',
            replaceprior = v_replace_prior,
            optpotential = 'High',
            alertcnt = alertcnt + 1,
            alertmoment = NEW.perfmoment
        WHERE alertreg = v_existing_alert_id;
    ELSE
        -- Generate a random hash for the alert ID
        v_random_hash := substr(md5(random()::text), 1, 8);

        -- Insert new critical alert
        INSERT INTO alerts (alertreg, compreg, deviceref, incidentref, alertmoment, alertstat, alertcnt, maintprior, replaceprior, optpotential)
        VALUES (
            'ALERT_' || v_random_hash,
            NEW.compreg,
            NEW.deviceref,
            NEW.perfregistry,
            NEW.perfmoment,
            'Critical',
            1,
            'High',
            v_replace_prior,
            'High'
        );
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

